/* === ROOT TOKENS === */
:root {
  /* neutrals *
  --rivo-white: #ffffff;
  --rivo-grey-100: #f2f5f4;
  --rivo-grey-300: #f4f4f4;
  --rivo-grey-400: #b0bfbc;

  /* accents */
  --rivo-vip-bg: #e5e5ff;
  --rivo-faq-bg: #e5e5ff;
  --rivo-zebra-even: #e5e5ff;
  --rivo-zebra-odd: #f2f2ff;
  --rivo-card-border: #3d4852;

  /* define in theme */
  /* --rivo-primary-color: ...; */
  /* --rivo-secondary-color: ...; */
}

/* === BUTTONS === */
.rivo-button,
.rivo-modal-button,
.rivo-points-table-load-more-button {
  background: var(--rivo-primary-color);
  color: var(--rivo-secondary-color);
  display: flex;
  justify-content: center;
  min-width: 180px;
  min-height: 50px;
  padding: 10px;
  border: 1px solid transparent;
  border-radius: 60px;
  line-height: 2;
}

.rivo-button:hover,
.rivo-modal-button:hover {
  opacity: 0.9;
}

.rivo-hero-buttons > .rivo-button:nth-of-type(2) {
  background: transparent;
  color: var(--rivo-primary-color);
  border: 1px solid var(--rivo-primary-color);
}
.rivo-hero-buttons > .rivo-button:nth-of-type(2):hover {
  background: transparent;
  color: var(--rivo-secondary-color);
  border: 1px solid var(--rivo-secondary-color);
}

.rivo-hero-buttons > .rivo-button:nth-of-type(2):hover {
}

.rivo-success-button {
  color: transparent !important;
}

.rivo-success-button:after {
  display: none;
}

.rivo-copy-button.rivo-success-button::before, button[aria-label="Copy coupon code"]::before {

}

.rivo-add-shipping-address,
.rivo-logout-link {
  display: flex;
}

.rivo-add-shipping-address a,
.rivo-logout-link a,
.rivo-form-row button[type=submit] {
  width: 100%;
  padding: 10px;
  text-align: center;
  border-radius: 6px;
}

/* copy-code placeholder */
.rivo-copy-button.rivo-success-button::before,
button[aria-label="Copy coupon code"]::before {
}

/* load-more */
.rivo-points-table-load-more-button {
  background: var(--rivo-primary-color);
  color: var(--rivo-secondary-color);
  padding: 10px;
  border: 0;
  border-radius: 4px;
  font-size: 16px;
  text-decoration: none;
}

/* form inputs */
input.rivo-coupon-code,
.rivo-multiplier-input .rivo-form-input,
input.rivo-form-input {
  border: 1px solid var(--rivo-primary-color);
  font-size: 16px !important;
  border-radius: 5px;
}

/* modal links */
.rivo-modal-p a {
  text-decoration: underline;
}

.rivo-modal-p a::after {
  content: ".";
}

/* === HERO === */
#rivo-lp-header {
  max-width: 95%;
   margin: 0 auto;
  padding: 20px;
  padding-left: 0;
}

.rivo-hero-description {
  max-width: 300px;
}

.rivo-hero-banner-media img {
  border-radius: 60px;
}

.rivo-content-wrapper {
  border-radius: 12px;
}

.rivo-hero-title img {
  display: block;
  margin: 0 auto 20px;
  height: 25px;
}

.rivo-hero-banner-wrapper {
  max-width: 1500px;
  padding-left: 20px;
}

.rivo-hero-banner-text {
  display: flex;
  flex-direction: column;
}

/* === TITLES === */
#rivo-how-it-works {
  width: 100%;
}

.rivo-section-label {
  display: block;
  font-size: 24px;
  color: var(--rivo-secondary-color);
  font-weight: 600;
}

/* === How it works === */

.rivo-step-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* === CARDS === */
.rivo-card {
  flex-basis: 30%;
}

.rivo-card-title {
  text-transform: capitalize;
}

.rivo-card-description {
  padding-top: 0;
}

.rivo-card-body {
  max-width: 95%;
  margin: 0 auto;
}

#rivo-ways-to-redeem .rivo-card img.custom-icon,
#rivo-lp-my-rewards .rivo-card img.custom-icon {
  height: 120px !important;
  width: 120px !important;
}


#rivo-ways-to-earn .rivo-card {
}

#rivo-ways-to-earn .rivo-card.completed:hover {
}

/* === FAQS === */

/* ----- VIP Tiers ----- */
td.rivo-vip-tier-table-row-perk-name {
  text-align: left;
  text-transform: uppercase;
  font-weight: 600;
  color: #000;
  background: transparent;
}

table.rivo-vip-tier-table {
   border-collapse: collapse;
}

span.rivo-th-tier-name {
  text-transform: uppercase;
  letter-spacing: 1px;
}

.rivo-vip-tier-table-thead-first-cell {
  background: #fff;
}

tbody tr,
td.rivo-vip-tier-table-row-perk-name,
tbody tr:nth-child(even) {
}

/* Tier 1 Header */
.rivo-vip-tier-table .rivo-tier-column-1 {
  background: #f6f6f6 !important;
  color: var(--rivo-primary-color);
}

/* Tier 2 Header */
.rivo-vip-tier-table .rivo-tier-column-2 {
  background: #00BADB !important;
}

/* Tier 3 Header */
.rivo-vip-tier-table .rivo-tier-column-3 {
  background: #000 !important;
  color: #fff;
}

/* Column 3 (fallback by position, if needed) */


/* Column 4 (fallback by position, if needed) */
.rivo-vip-tier-table th:nth-child(4) {
  color: #fff;
}

tr.rivo-vip-tier-table-tbody-row td.rivo-tier-column-2 {
  color: #fff;
}

@media (max-width: 768px) {
  #rivo-ways-to-redeem .rivo-card,
  #rivo-lp-my-rewards .rivo-card {
    padding-bottom: 10px;
  }

  #rivo-ways-to-redeem .rivo-card-icon img,
  #rivo-lp-my-rewards .rivo-card-icon img {
    height: 100px !important;
    width: 100px !important;
  }

  .rivo-how-it-works-step-image img {
    height: 100px;
  }
}

/* === VIP PROGRESS BAR === */
.rivo-vip-tier-progress-container {
  width: 50%;
}

@media (max-width: 768px) {
  .rivo-vip-tier-progress-container {
    width: 95%;
  }
}

.rivo-account-progress-container {
  background: var(--rivo-grey-300);
}

.rivo-account-progress-bar {
  background: var(--rivo-primary-color);
}

.rivo-progress-current-tier-label,
.rivo-progress-next-tier-label {
  text-transform: uppercase;
}

/* === ACTIVITY / LOGS === */
.rivo-points-expiry {
  padding: 10px;
  color: var(--rivo-primary-color);
  font-weight: 900;
  font-size: 14px;
  margin: 16px auto 0;
  width: fit-content;
}

#points-logs-activity thead th {
  background: var(--rivo-primary-color);
  color: var(--rivo-secondary-color);
  font-weight: 500;
}

#points-logs-activity td {
  color: var(--rivo-primary-color);
}

/* === SCROLLBARS === */
.rivo-lp-cards-container::-webkit-scrollbar,
.rivo-vip-tier-container::-webkit-scrollbar {
  width: 10px;
  height: 8px;
}

.rivo-lp-cards-container::-webkit-scrollbar-track,
.rivo-vip-tier-container::-webkit-scrollbar-track {
  background: var(--rivo-vip-bg);
  border-radius: 10px;
}

.rivo-lp-cards-container::-webkit-scrollbar-thumb,
.rivo-vip-tier-container::-webkit-scrollbar-thumb {
  background: var(--rivo-secondary-color);
  border-radius: 10px;
}

/* === MOBILE ≤768px === */
@media (max-width: 768px) {
  .rivo-hero-banner-text {
    padding: 40px;
  }

#rivo-lp-header { 
  width: 100%;
  padding: 10px;
}

.rivo-hero-banner-wrapper {
  padding-left: 0;
}

.rivo-hero-banner-text {
  padding-left: 20px;
}


.rivo-hero-buttons > .rivo-button:nth-of-type(2) {
  border-color: var(--rivo-secondary-color);
  color: var(--rivo-secondary-color);
}

.rivo-hero-buttons > .rivo-button {
  background: var(--rivo-secondary-color);
  color: var(--rivo-primary-color);
}


  .rivo-content-wrapper {
    padding: 40px 0;
  }

  .rivo-modal-button {
    background: var(--rivo-primary-color);
  }

  .rivo-section-label {
    font-size: 16px;
  }

  .rivo-card-title {
    font-size: 16px;
  }

  .rivo-card-description {
    font-size: 14px;
  }

  .rivo-vip-tier-container {
    padding-bottom: 20px;
  }

  table.rivo-vip-tier-table {
    padding-bottom: 20px;
  }

  table.rivo-vip-tier-table th,
  table.rivo-vip-tier-table td {
    width: 200px;
    height: 60px;
  }
}
.rivo-modal-cta {
display: block;
}
